def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    for index, operation in enumerate(ops):
        tokens = operation.split(" ")
        verb = tokens[0]

        if verb not in arities or len(tokens) != arities[verb]:
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue

            for account, old_balance, was_frozen in history.pop():
                if old_balance is None:
                    del balances[account]
                    frozen.discard(account)
                else:
                    balances[account] = old_balance
                    if was_frozen:
                        frozen.add(account)
                    else:
                        frozen.discard(account)
            continue

        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount_token = tokens[-1]
            if not amount_token or any(
                char < "0" or char > "9" for char in amount_token
            ):
                rejected.append(index)
                continue

            # Convert in small chunks so arbitrarily long valid amounts work.
            amount = 0
            for start in range(0, len(amount_token), 9):
                chunk = amount_token[start:start + 9]
                amount = amount * (10 ** len(chunk)) + int(chunk)

            if verb != "open" and amount == 0:
                rejected.append(index)
                continue

        account = tokens[1]

        if verb == "open":
            if account in balances:
                rejected.append(index)
                continue
            history.append([(account, None, False)])
            balances[account] = amount

        elif verb == "deposit":
            if account not in balances:
                rejected.append(index)
                continue
            history.append([(account, balances[account], account in frozen)])
            balances[account] += amount

        elif verb == "withdraw":
            if (
                account not in balances
                or account in frozen
                or balances[account] < amount
            ):
                rejected.append(index)
                continue
            history.append([(account, balances[account], False)])
            balances[account] -= amount

        elif verb == "transfer":
            destination = tokens[2]
            if (
                account == destination
                or account not in balances
                or destination not in balances
                or account in frozen
                or balances[account] < amount
            ):
                rejected.append(index)
                continue
            history.append([
                (account, balances[account], False),
                (destination, balances[destination], destination in frozen),
            ])
            balances[account] -= amount
            balances[destination] += amount

        elif verb == "freeze":
            if account not in balances or account in frozen:
                rejected.append(index)
                continue
            history.append([(account, balances[account], False)])
            frozen.add(account)

        else:  # unfreeze
            if account not in balances or account not in frozen:
                rejected.append(index)
                continue
            history.append([(account, balances[account], True)])
            frozen.remove(account)

    return balances, rejected
